CREATE TABLE "usuario" (
  "id_usuario" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(100),
  "apellido" varchar(100),
  "email" varchar(150) UNIQUE NOT NULL,
  "password" varchar(255) NOT NULL,
  "telefono" varchar(30),
  "rol" varchar(20) NOT NULL,
  "estado" varchar(20),
  "fecha_registro" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "proveedor" (
  "id_proveedor" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(150) NOT NULL,
  "telefono" varchar(30),
  "email" varchar(150),
  "direccion" varchar(255),
  "estado" varchar(20),
  "fecha_registro" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "categoria" (
  "id_categoria" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(100) UNIQUE NOT NULL,
  "descripcion" text,
  "estado" varchar(20)
);

CREATE TABLE "producto" (
  "id_producto" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_proveedor" int NOT NULL,
  "id_categoria" int NOT NULL,
  "nombre" varchar(150) NOT NULL,
  "descripcion" text,
  "precio" decimal(10,2) NOT NULL CHECK ("precio" >= 0),
  "stock" int NOT NULL CHECK ("stock" >= 0),
  "imagen" varchar(255),
  "estado" varchar(20),
  "fecha_publicacion" timestamp DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "direccion" (
  "id_direccion" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_usuario" int NOT NULL,
  "departamento" varchar(100),
  "ciudad" varchar(100),
  "zona" varchar(100),
  "direccion" varchar(255),
  "referencia" varchar(255),
  "telefono" varchar(30)
);

CREATE TABLE "carrito" (
  "id_carrito" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_usuario" int NOT NULL,
  "fecha_creacion" timestamp DEFAULT CURRENT_TIMESTAMP,
  "estado" varchar(20)
);

CREATE TABLE "carrito_detalle" (
  "id_detalle" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_carrito" int NOT NULL,
  "id_producto" int NOT NULL,
  "cantidad" int NOT NULL CHECK ("cantidad" > 0), UNIQUE ("id_carrito", "id_producto")
);

CREATE TABLE "pedido" (
  "id_pedido" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_usuario" int NOT NULL,
  "id_direccion" int NOT NULL,
  "fecha_pedido" timestamp DEFAULT CURRENT_TIMESTAMP,
  "estado" varchar(30),
  "subtotal_productos" decimal(10,2) CHECK ("subtotal_productos" >= 0),
  "costo_envio" decimal(10,2) CHECK ("costo_envio" >= 0),
  "descuento" decimal(10,2) CHECK ("descuento" >= 0),
  "total" decimal(10,2) NOT NULL CHECK ("total" >= 0)
);

CREATE TABLE "pedido_proveedor" (
  "id_pedido_proveedor" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_pedido" int NOT NULL,
  "id_proveedor" int NOT NULL,
  "subtotal" decimal(10,2) NOT NULL CHECK ("subtotal" >= 0),
  "estado" varchar(30)
);

CREATE TABLE "pedido_detalle" (
  "id_detalle" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_pedido_proveedor" int NOT NULL,
  "id_producto" int NOT NULL,
  "cantidad" int NOT NULL CHECK ("cantidad" > 0),
  "precio_unitario" decimal(10,2) NOT NULL CHECK ("precio_unitario" >= 0),
  "subtotal" decimal(10,2) NOT NULL CHECK ("subtotal" >= 0)
);

CREATE TABLE "pago" (
  "id_pago" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_pedido" int NOT NULL,
  "metodo_pago" varchar(50),
  "monto" decimal(10,2) NOT NULL CHECK ("monto" >= 0),
  "estado" varchar(30),
  "fecha_pago" timestamp DEFAULT CURRENT_TIMESTAMP
);


-- ==========================================================
-- CLAVES FORÁNEAS
-- ==========================================================

ALTER TABLE "producto" ADD FOREIGN KEY ("id_proveedor") REFERENCES "proveedor" ("id_proveedor") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "producto" ADD FOREIGN KEY ("id_categoria") REFERENCES "categoria" ("id_categoria") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "direccion" ADD FOREIGN KEY ("id_usuario") REFERENCES "usuario" ("id_usuario") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "carrito" ADD FOREIGN KEY ("id_usuario") REFERENCES "usuario" ("id_usuario") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "carrito_detalle" ADD FOREIGN KEY ("id_carrito") REFERENCES "carrito" ("id_carrito") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "carrito_detalle" ADD FOREIGN KEY ("id_producto") REFERENCES "producto" ("id_producto") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pedido" ADD FOREIGN KEY ("id_usuario") REFERENCES "usuario" ("id_usuario") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pedido" ADD FOREIGN KEY ("id_direccion") REFERENCES "direccion" ("id_direccion") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pedido_proveedor" ADD FOREIGN KEY ("id_pedido") REFERENCES "pedido" ("id_pedido") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pedido_proveedor" ADD FOREIGN KEY ("id_proveedor") REFERENCES "proveedor" ("id_proveedor") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pedido_detalle" ADD FOREIGN KEY ("id_pedido_proveedor") REFERENCES "pedido_proveedor" ("id_pedido_proveedor") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pedido_detalle" ADD FOREIGN KEY ("id_producto") REFERENCES "producto" ("id_producto") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pago" ADD FOREIGN KEY ("id_pedido") REFERENCES "pedido" ("id_pedido") DEFERRABLE INITIALLY IMMEDIATE;